(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    await m.actions.ensureKernel();
    if (m.state.editing) m.actions.cancelEditing({ quiet: true });
    await m.actions.closeProject({ force: true });
    await m.actions.openSampleAsk('asmRobot'); await sleep(1500);
    const keys = [...m.viewport.bodies.keys()].filter((k) => k.startsWith('comp:'));
    const mat = (k) => [...m.viewport.bodies.get(k).mesh.matrix.elements];
    const at0 = new Map(keys.map((k) => [k, mat(k)]));
    const slider = document.querySelector('#motion-bar [data-player-time]');
    if (!slider) return 'no player slider';
    const changed = new Set();
    for (const t of [0.8, 1.6, 2.5, 3.7]) {
      slider.value = String(t); slider.dispatchEvent(new Event('input', { bubbles: true })); await sleep(200);
      for (const k of keys) { const a = at0.get(k); const b = mat(k); if (a.some((v, i) => Math.abs(v - b[i]) > 1e-6)) changed.add(k); }
    }
    const names = (k) => { const id = k.slice(5).split('/'); const c = m.active().components.find((x) => x.id === id[0]); return id.length > 1 ? `${c?.name}/${m.project.assemblies.flatMap((a) => a.components).find((x) => x.id === id[1])?.name}` : c?.name; };
    const still = keys.filter((k) => !changed.has(k)).map(names);
    return `${keys.length} bodies, ${changed.size} moved; still: ${still.join(', ')}`;
